/**
 * Covenant Stars
 * --------------
 * God promises Abram descendants as numberless as the stars and seals the covenant in fire. Stage: Abram alone outside his tent at midnight, wrapped in a cloak, staring into a sky crowded with stars; a smoking fire pot and blazing torch passing between cut animals; deep indigo, ember orange.
 *
 * Palette 0xd8b878 → 0x9c8456 · light: dawn · hero: fire
 * Game beat: Trace the promised constellation.
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./abraham-kit.js.
 */

import { THREE, createScene, tent, firepit, jar, oak, flame, person } from './abraham-kit.js';

const BG = 0xd8b878;
const GROUND = 0x776542;

export function build(group) {
    const W = createScene(group, { seed: 2360355061, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* ground */
    W.ground(260, 260, 0, 0, 0x776542, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* camp: a circle of tents, smoke rising */
    tent(W, group, -29.5, 0, -10.8, 1.14, 0xd8c8a0, W.r() * 6);
    tent(W, group, -0.5, 0, -21.2, 1.30, 0xd8c8a0, W.r() * 6);
    tent(W, group, -13.3, 0, -0.5, 1.03, 0x8a6a44, W.r() * 6);
    firepit(W, group, 3.4, 0, -2.0, 1.0);

    jar(W, group, 7.1, 0, 6.9, );

    /* hero: the burning bush */
    oak(W, group, 0, 0, 0, 0.75, { leaf: 0x3a4a20, leaf2: 0x4a5a28 });
    flame(W, group, 0, 1.4, 0, 1.0);
    W.point(0xff8a30, 2.4, 60, 0, 3, 0, 0.4);
    W.disc([0, 6, -12], 7, 0xffa050, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0xd8b878, ry: -0.45, s: 1.02 });

    return W.finish();
}

export default { build };
